<?php
require 'includes/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$d=[trim($_POST['nome']??''),trim($_POST['documento']??''),trim($_POST['contato']??''),trim($_POST['email']??''),trim($_POST['telefone']??''),trim($_POST['endereco']??''),trim($_POST['cidade']??''),strtoupper(trim($_POST['uf']??'')),trim($_POST['observacoes']??'')];if(!$d[0]){flash('error','Informe o nome do cliente.');redirect('clientes.php');}if($id){$pdo->prepare("UPDATE clientes SET nome=?,documento=?,contato=?,email=?,telefone=?,endereco=?,cidade=?,uf=?,observacoes=? WHERE id=?")->execute([...$d,$id]);}else{$pdo->prepare("INSERT INTO clientes(nome,documento,contato,email,telefone,endereco,cidade,uf,observacoes) VALUES(?,?,?,?,?,?,?,?,?)")->execute($d);}flash('success','Cliente salvo.');redirect('clientes.php');}
if(isset($_GET['desativar'])){$pdo->prepare("UPDATE clientes SET ativo=0 WHERE id=?")->execute([(int)$_GET['desativar']]);flash('success','Cliente desativado.');redirect('clientes.php');}
$edit=null;if(isset($_GET['editar'])){$st=$pdo->prepare("SELECT * FROM clientes WHERE id=?");$st->execute([(int)$_GET['editar']]);$edit=$st->fetch();}$lista=$pdo->query("SELECT * FROM clientes WHERE ativo=1 ORDER BY nome")->fetchAll();require 'includes/header.php';?>
<div class="page-head"><h1>Clientes</h1></div><form class="card" method="post"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-grid"><div><label>Nome / Empresa *</label><input name="nome" required value="<?= e($edit['nome']??'') ?>"></div><div><label>CPF/CNPJ</label><input name="documento" value="<?= e($edit['documento']??'') ?>"></div><div><label>Contato</label><input name="contato" value="<?= e($edit['contato']??'') ?>"></div><div><label>E-mail</label><input type="email" name="email" value="<?= e($edit['email']??'') ?>"></div><div><label>Telefone</label><input name="telefone" value="<?= e($edit['telefone']??'') ?>"></div><div><label>Endereço</label><input name="endereco" value="<?= e($edit['endereco']??'') ?>"></div><div><label>Cidade</label><input name="cidade" value="<?= e($edit['cidade']??'') ?>"></div><div><label>UF</label><input maxlength="2" name="uf" value="<?= e($edit['uf']??'') ?>"></div><div class="full"><label>Observações</label><textarea name="observacoes"><?= e($edit['observacoes']??'') ?></textarea></div></div><p><button class="btn">Salvar cliente</button></p></form>
<h2>Clientes ativos</h2><table><thead><tr><th>Nome</th><th>Documento</th><th>Contato</th><th>Telefone</th><th></th></tr></thead><tbody><?php foreach($lista as $r):?><tr><td><?= e($r['nome']) ?></td><td><?= e($r['documento']) ?></td><td><?= e($r['contato']) ?></td><td><?= e($r['telefone']) ?></td><td class="actions"><a class="btn secondary" href="?editar=<?= (int)$r['id'] ?>">Editar</a><a data-confirm="Desativar este cliente?" class="btn danger" href="?desativar=<?= (int)$r['id'] ?>">Desativar</a></td></tr><?php endforeach;?></tbody></table><?php require 'includes/footer.php';?>
